from dataclasses import dataclass


@dataclass(frozen=True)
class Chunk:
    doc_id: str
    start: int  # where text[0] is in the original document
    text: str


def chunk_by_paragraph(doc_id, text):
    """One chunk per blank-line-separated paragraph, with surrounding whitespace trimmed."""
    chunks = []
    position = 0
    for raw in text.split("\n\n"):
        trimmed = raw.strip()
        if trimmed:
            chunks.append(Chunk(doc_id, position, trimmed))
        position += len(raw) + 2
    return chunks

