import re

_WORD = re.compile(r"[a-z0-9]+")


def best_chunk(chunks, query):
    """The chunk that shares the most words with the query."""
    wanted = set(_WORD.findall(query.lower()))
    return max(chunks, key=lambda c: len(wanted & set(_WORD.findall(c.text.lower()))))

