import unittest

from answer import cite
from chunker import chunk_by_paragraph

DOC = "Intro.\n\n   The warranty lasts two years.\n\n\nSupport is open on weekdays."


class Regression(unittest.TestCase):
    def test_chunk_text_has_no_surrounding_whitespace(self):
        for chunk in chunk_by_paragraph("terms", DOC):
            self.assertEqual(chunk.text, chunk.text.strip())

    def test_blank_paragraphs_are_skipped(self):
        texts = [c.text for c in chunk_by_paragraph("terms", DOC)]
        self.assertEqual(texts, ["Intro.", "The warranty lasts two years.", "Support is open on weekdays."])

    def test_a_quote_from_the_last_paragraph_is_cited_correctly(self):
        chunks = chunk_by_paragraph("terms", DOC)
        citation = cite(chunks[-1], "open on weekdays")
        self.assertEqual(DOC[citation.start : citation.end], "open on weekdays")

    def test_a_quote_that_is_not_in_the_chunk_is_refused(self):
        with self.assertRaises(ValueError):
            cite(chunk_by_paragraph("terms", DOC)[0], "warranty")

